"""Modern retry wrapper preserving Meridian CRM retry-count semantics."""

from collections.abc import Callable
from typing import Any


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(endpoint_cfg: dict, transport: Callable[[str, int], Any]) -> dict:
    """Call an injected transport with the configured retry attempt budget."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    total_attempts = endpoint_cfg["retry"] + 1

    for attempts in range(1, total_attempts + 1):
        try:
            result = transport(url, timeout_ms)
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }
        except PermanentError as error:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(error),
                },
            }
        except TransientError as error:
            if attempts == total_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(error),
                    },
                }

    raise RuntimeError("unreachable")
